    public static function svg(string $name, ?int $size = null, string $class = ''): string
    {
        $inner = self::PATHS[$name] ?? '';
        $classes = trim('icon icon-'.$name.' '.$class);
        $dims = $size ? sprintf(' width="%1$d" height="%1$d"', $size) : '';

        return '<svg class="'.e($classes).'"'.$dims.' viewBox="0 0 24 24" fill="none" stroke="currentColor"'
            .' stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">'
            .$inner.'</svg>';
    }
